import pandas as pd


class Student:
    """One student with validation."""

    def __init__(self, roll, name, course, marks):
        if not isinstance(roll, int) or roll <= 0:
            raise ValueError("Roll number must be a positive integer")
        if not name.strip():
            raise ValueError("Name cannot be empty")
        if not 0 <= marks <= 100:
            raise ValueError("Marks must be between 0 and 100")
        self.roll = roll
        self.name = name.strip().title()
        self.course = course.strip().title()
        self.marks = float(marks)

    @property
    def grade(self):
        if self.marks >= 90: return "A+"
        if self.marks >= 80: return "A"
        if self.marks >= 70: return "B"
        if self.marks >= 60: return "C"
        if self.marks >= 50: return "D"
        return "F"

    def to_dict(self):
        return {"Roll": self.roll, "Name": self.name, "Course": self.course,
                "Marks": self.marks, "Grade": self.grade}

    def __str__(self):
        return f"[{self.roll}] {self.name:<10} {self.course:<8} {self.marks:>5.1f}  {self.grade}"


class RecordBook:
    """A collection of students with file saving."""

    def __init__(self, filename="records.csv"):
        self.filename = filename
        self.students = {}                       # roll -> Student

    def add(self, student):
        if student.roll in self.students:
            raise KeyError(f"Roll {student.roll} already exists")
        self.students[student.roll] = student

    def remove(self, roll):
        if roll not in self.students:
            raise KeyError(f"Roll {roll} not found")
        del self.students[roll]

    def search(self, text):
        text = text.lower()
        return [s for s in self.students.values() if text in s.name.lower()]

    def to_dataframe(self):
        return pd.DataFrame([s.to_dict() for s in self.students.values()])

    def save(self):
        self.to_dataframe().to_csv(self.filename, index=False)

    def load(self):
        if not os.path.exists(self.filename):
            return
        df = pd.read_csv(self.filename)
        for _, row in df.iterrows():
            self.add(Student(int(row["Roll"]), row["Name"], row["Course"], float(row["Marks"])))

print("Classes defined")

def run_menu():
    book = RecordBook("records.csv")
    book.load()

    while True:
        print("\n===== STUDENT RECORDS MANAGER =====")
        print("1. Add student   2. Remove student   3. Search")
        print("4. Show all      5. Statistics        6. Save & Exit")
