                book.add(Student(roll, name, course, marks))
                print("Student added")
            elif choice == "2":
                book.remove(int(input("Roll no to remove: ")))
                print("Removed")
            elif choice == "3":
                for s in book.search(input("Name contains: ")):
                    print(s)
            elif choice == "4":
                if book.students:
                    print(book.to_dataframe().to_string(index=False))
                else:
                    print("No records yet")
            elif choice == "5":
                if book.students:
                    print(book.to_dataframe()["Marks"].describe().round(2))
                else:
                    print("No records yet")
            elif choice == "6":
                book.save()
                print("Saved. Goodbye!")
                break
            else:
                print("Invalid choice")
        except ValueError as e:
            print("Input error:", e)
        except KeyError as e:
            print("Record error:", e)

run_menu()
